WATCHES = [
    ("middle", 0, 240),
    ("morning", 240, 480),
    ("forenoon", 480, 720),
    ("afternoon", 720, 960),
    ("first dog", 960, 1080),
    ("last dog", 1080, 1200),
    ("first", 1200, 1440),
]


def _check(minute):
    if not 0 <= minute < 1440:
        raise ValueError(f"minute out of range: {minute!r}")


def watch_at(minute):
    _check(minute)
    for name, start, end in WATCHES:
        if start <= minute < end:
            return name


def bells_at(minute):
    _check(minute)
    if minute % 30:
        return 0
    t = minute if minute else 1440
    for _, start, end in WATCHES:
        if start < t <= end:
            return (t - start) // 30

